 6	 */
 7	public abstract class AbstractMovementStrategy implements MovementStrategy
 8	{
 9	    private static final Random rand = Randomizer.getRandom();
10	
11	    protected void moveOrHandleBlocked(Animal animal, Location newLocation)
12	    {
13	        if(newLocation != null) {
14	            animal.setLocation(newLocation);
15	        }
16	        else if(moveToAdjacentGrass(animal)) {
17	            return;
18	        }
19	        else if(animal.diesFromOvercrowding()) {
