22	    }
23	
24	    private boolean moveToAdjacentGrass(Animal animal)
25	    {
26	        List<Location> adjacentGrassSpots = animal.getField().adjacentLocationsWithSpecies(animal.getLocation(), Grass.class);
27	        if(adjacentGrassSpots.isEmpty()) {
28	            return false;
29	        }
30	
31	        animal.getField().clear(animal.getLocation());
32	        animal.setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
33	        return true;
34	    }
35	}
